          sessionId = after.sessionId;
          const newOnes = diffNewElements(before, after.elements);
          for (const e9 of newOnes) {
            if (!e9.bbox && capturedBounds.has(e9.name)) e9.bbox = capturedBounds.get(e9.name);
          }
          elements = [...before, ...newOnes];
